def solve(xs):
    if not xs:
        return ""

    prefix = xs[0]
    for i in range(1, len(xs)):
        while xs[i].startswith(prefix) == False:
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix
```

